def choose_move(observation):
    wx, hy = observation['grid_width'], observation['grid_height']
    ax, ay = observation['self_position']
    ox, oy = observation['opponent_position']
    res = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    score_self = observation.get('scores', [0])[0]
    score_opp = observation.get('scores', [0])[1]

    def safe_move(dx, dy):
        nx, ny = ax + dx, ay + dy
        if 0 <= nx < wx and 0 <= ny < hy and (nx, ny) not in obstacles:
            return (nx, ny)
        return None

    # Check directions: prioritize towards resources
    directions = [ (0,1), (1,0), (0,-1), (-1,0) ]
    best_move = None
    best_dist = float('inf')

    for dx, dy in directions:
        nxt = safe_move(dx, dy)
        if nxt:
            dist = min((res_x - nxt[0])**2 + (res_y - nxt[1])**2 for res_x, res_y in res) if res else 0
            if dist < best_dist:
                best_dist = dist
                best_move = (dx, dy)

    # If no resource or blocked, try random safe move
    if not best_move:
        for dx, dy in directions:
            if safe_move(dx, dy):
                best_move = (dx, dy)
                break
    # If all blocked, stay in place
    if not best_move:
        return [0, 0]
    return list(best_move)
